{
  "rule": "Start with the ball in the middle and a hidden orientation that is normal. Shake flips this orientation; tilt left moves the ball one slot left when normal and one slot right when flipped, while tilt right moves it one slot right when normal and one slot left when flipped, stopping at the boundaries.",
  "commitments": [
    {
      "events": ["shake", "tilt left", "tilt left"],
      "predict": "right",
      "why": "If this ended left or middle, then a shake would not be reversing the next tilts, or boundary behavior after reversal would be wrong."
    },
    {
      "events": ["tilt left", "shake", "tilt left"],
      "predict": "middle",
      "why": "If this ended left, the shake would not be flipping the direction of the second tilt, contradicting the hidden-orientation rule."
    },
    {
      "events": ["tilt left", "tilt left", "shake", "tilt left"],
      "predict": "middle",
      "why": "If this ended left, the rule would be mishandling the boundary at left followed by a reversed left tilt."
    },
    {
      "events": ["shake", "shake", "tilt left"],
      "predict": "left",
      "why": "If this ended middle or right, then two shakes would not cancel, so shake would not be a simple orientation toggle."
    },
    {
      "events": ["shake", "tilt left", "shake", "tilt left"],
      "predict": "middle",
      "why": "If this ended right or left, the parity after two shakes would not be tracked correctly as the same as normal."
    }
  ]
}
